   431  void Parser::ParseLV1SceneBlock() {
   432      AI_ASE_PARSER_INIT();
   433      while (true) {
   434          if ('*' == *filePtr) {
   435              ++filePtr;
   436              if (TokenMatch(filePtr, "SCENE_BACKGROUND_STATIC", 23))
   437
   438              {
   439                  // parse a color triple and assume it is really the bg color
   440                  ParseLV4MeshFloatTriple(&m_clrBackground.r);
   441                  continue;
   442              }
   443              if (TokenMatch(filePtr, "SCENE_AMBIENT_STATIC", 20))
   444
   445              {
   446                  // parse a color triple and assume it is really the bg color
   447                  ParseLV4MeshFloatTriple(&m_clrAmbient.r);
   448                  continue;
   449              }
   450              if (TokenMatch(filePtr, "SCENE_FIRSTFRAME", 16)) {
   451                  ParseLV4MeshLong(iFirstFrame);
   452                  continue;
   453              }
   454              if (TokenMatch(filePtr, "SCENE_LASTFRAME", 15)) {
   455                  ParseLV4MeshLong(iLastFrame);
   456                  continue;
   457              }
   458              if (TokenMatch(filePtr, "SCENE_FRAMESPEED", 16)) {
   459                  ParseLV4MeshLong(iFrameSpeed);
   460                  continue;
   461              }
   462              if (TokenMatch(filePtr, "SCENE_TICKSPERFRAME", 19)) {
   463                  ParseLV4MeshLong(iTicksPerFrame);
   464                  continue;
   465              }
   466          }
   467          AI_ASE_HANDLE_TOP_LEVEL_SECTION();
   468      }
   469  }
