   472  void Parser::ParseLV1MaterialListBlock() {
   473      AI_ASE_PARSER_INIT();
   474
   475      unsigned int iMaterialCount = 0;
   476      unsigned int iOldMaterialCount = (unsigned int)m_vMaterials.size();
   477      while (true) {
   478          if ('*' == *filePtr) {
   479              ++filePtr;
   480              if (TokenMatch(filePtr, "MATERIAL_COUNT", 14)) {
   481                  ParseLV4MeshLong(iMaterialCount);
   482
   483                  // now allocate enough storage to hold all materials
   484                  m_vMaterials.resize(iOldMaterialCount + iMaterialCount, Material("INVALID"));
   485                  continue;
   486              }
   487              if (TokenMatch(filePtr, "MATERIAL", 8)) {
   488                  unsigned int iIndex = 0;
   489                  ParseLV4MeshLong(iIndex);
   490
   491                  if (iIndex >= iMaterialCount) {
   492                      LogWarning("Out of range: material index is too large");
   493                      iIndex = iMaterialCount - 1;
   494                      return;
   495                  }
   496
   497                  // get a reference to the material
   498                  Material &sMat = m_vMaterials[iIndex + iOldMaterialCount];
   499                  // parse the material block
   500                  ParseLV2MaterialBlock(sMat);
   501                  continue;
   502              }
   503              if( iDepth == 1 ){
   504                  // CRUDE HACK: support missing brace after "Ascii Scene Exporter v2.51"
   505                  LogWarning("Missing closing brace in material list");
   506                  --filePtr;
   507                  return;
   508              }
   509          }
   510          AI_ASE_HANDLE_TOP_LEVEL_SECTION();
   511      }
   512  }
