   515  void Parser::ParseLV2MaterialBlock(ASE::Material &mat) {
   516      AI_ASE_PARSER_INIT();
   517
   518      unsigned int iNumSubMaterials = 0;
   519      while (true) {
   520          if ('*' == *filePtr) {
   521              ++filePtr;
   522              if (TokenMatch(filePtr, "MATERIAL_NAME", 13)) {
   523                  if (!ParseString(mat.mName, "*MATERIAL_NAME"))
   524                      SkipToNextToken();
   525                  continue;
   526              }
   527              // ambient material color
   528              if (TokenMatch(filePtr, "MATERIAL_AMBIENT", 16)) {
   529                  ParseLV4MeshFloatTriple(&mat.mAmbient.r);
   530                  continue;
   531              }
   532              // diffuse material color
   533              if (TokenMatch(filePtr, "MATERIAL_DIFFUSE", 16)) {
   534                  ParseLV4MeshFloatTriple(&mat.mDiffuse.r);
   535                  continue;
   536              }
   537              // specular material color
   538              if (TokenMatch(filePtr, "MATERIAL_SPECULAR", 17)) {
   539                  ParseLV4MeshFloatTriple(&mat.mSpecular.r);
   540                  continue;
   541              }
   542              // material shading type
   543              if (TokenMatch(filePtr, "MATERIAL_SHADING", 16)) {
   544                  if (TokenMatch(filePtr, "Blinn", 5)) {
   545                      mat.mShading = Discreet3DS::Blinn;
   546                  } else if (TokenMatch(filePtr, "Phong", 5)) {
   547                      mat.mShading = Discreet3DS::Phong;
   548                  } else if (TokenMatch(filePtr, "Flat", 4)) {
   549                      mat.mShading = Discreet3DS::Flat;
   550                  } else if (TokenMatch(filePtr, "Wire", 4)) {
   551                      mat.mShading = Discreet3DS::Wire;
   552                  } else {
   553                      // assume gouraud shading
   554                      mat.mShading = Discreet3DS::Gouraud;
   555                      SkipToNextToken();
   556                  }
   557                  continue;
   558              }
   559              // material transparency
   560              if (TokenMatch(filePtr, "MATERIAL_TRANSPARENCY", 21)) {
   561                  ParseLV4MeshFloat(mat.mTransparency);
   562                  mat.mTransparency = ai_real(1.0) - mat.mTransparency;
   563                  continue;
   564              }
   565              // material self illumination
   566              if (TokenMatch(filePtr, "MATERIAL_SELFILLUM", 18)) {
   567                  ai_real f = 0.0;
   568                  ParseLV4MeshFloat(f);
   569
   570                  mat.mEmissive.r = f;
   571                  mat.mEmissive.g = f;
   572                  mat.mEmissive.b = f;
   573                  continue;
   574              }
   575              // material shininess
   576              if (TokenMatch(filePtr, "MATERIAL_SHINE", 14)) {
   577                  ParseLV4MeshFloat(mat.mSpecularExponent);
   578                  mat.mSpecularExponent *= 15;
   579                  continue;
   580              }
   581              // two-sided material
   582              if (TokenMatch(filePtr, "MATERIAL_TWOSIDED", 17)) {
   583                  mat.mTwoSided = true;
   584                  continue;
   585              }
   586              // material shininess strength
   587              if (TokenMatch(filePtr, "MATERIAL_SHINESTRENGTH", 22)) {
   588                  ParseLV4MeshFloat(mat.mShininessStrength);
   589                  continue;
   590              }
   591              // diffuse color map
   592              if (TokenMatch(filePtr, "MAP_DIFFUSE", 11)) {
   593                  // parse the texture block
   594                  ParseLV3MapBlock(mat.sTexDiffuse);
   595                  continue;
   596              }
   597              // ambient color map
   598              if (TokenMatch(filePtr, "MAP_AMBIENT", 11)) {
   599                  // parse the texture block
   600                  ParseLV3MapBlock(mat.sTexAmbient);
   601                  continue;
   602              }
   603              // specular color map
   604              if (TokenMatch(filePtr, "MAP_SPECULAR", 12)) {
   605                  // parse the texture block
   606                  ParseLV3MapBlock(mat.sTexSpecular);
   607                  continue;
   608              }
   609              // opacity map
   610              if (TokenMatch(filePtr, "MAP_OPACITY", 11)) {
   611                  // parse the texture block
   612                  ParseLV3MapBlock(mat.sTexOpacity);
   613                  continue;
   614              }
   615              // emissive map
   616              if (TokenMatch(filePtr, "MAP_SELFILLUM", 13)) {
   617                  // parse the texture block
   618                  ParseLV3MapBlock(mat.sTexEmissive);
   619                  continue;
   620              }
   621              // bump map
   622              if (TokenMatch(filePtr, "MAP_BUMP", 8)) {
   623                  // parse the texture block
   624                  ParseLV3MapBlock(mat.sTexBump);
   625              }
   626              // specular/shininess map
   627              if (TokenMatch(filePtr, "MAP_SHINESTRENGTH", 17)) {
   628                  // parse the texture block
   629                  ParseLV3MapBlock(mat.sTexShininess);
   630                  continue;
   631              }
   632              // number of submaterials
   633              if (TokenMatch(filePtr, "NUMSUBMTLS", 10)) {
   634                  ParseLV4MeshLong(iNumSubMaterials);
   635
   636                  // allocate enough storage
   637                  mat.avSubMaterials.resize(iNumSubMaterials, Material("INVALID SUBMATERIAL"));
   638              }
   639              // submaterial chunks
   640              if (TokenMatch(filePtr, "SUBMATERIAL", 11)) {
   641
   642                  unsigned int iIndex = 0;
   643                  ParseLV4MeshLong(iIndex);
   644
   645                  if (iIndex >= iNumSubMaterials) {
   646                      LogWarning("Out of range: submaterial index is too large");
   647                      iIndex = iNumSubMaterials - 1;
   648                  }
   649
   650                  // get a reference to the material
   651                  if (iIndex < mat.avSubMaterials.size()) {
   652                      Material &sMat = mat.avSubMaterials[iIndex];
   653
   654                      // parse the material block
   655                      ParseLV2MaterialBlock(sMat);
   656                  }
   657
   658                  continue;
   659              }
   660          }
   661          AI_ASE_HANDLE_SECTION("2", "*MATERIAL");
   662      }
   663  }
