  1186  // ------------------------------------------------------------------------------------------------
  1187  // Setup proper material indices and build output materials
  1188  void ASEImporter::BuildMaterialIndices() {
  1189      ai_assert(nullptr != pcScene);
  1190
  1191      // iterate through all materials and check whether we need them
  1192      for (unsigned int iMat = 0; iMat < mParser->m_vMaterials.size(); ++iMat) {
  1193          ASE::Material &mat = mParser->m_vMaterials[iMat];
  1194          if (mat.bNeed) {
  1195              // Convert it to the aiMaterial layout
  1196              ConvertMaterial(mat);
  1197              ++pcScene->mNumMaterials;
  1198          }
  1199          for (unsigned int iSubMat = 0; iSubMat < mat.avSubMaterials.size(); ++iSubMat) {
  1200              ASE::Material &submat = mat.avSubMaterials[iSubMat];
  1201              if (submat.bNeed) {
  1202                  // Convert it to the aiMaterial layout
  1203                  ConvertMaterial(submat);
  1204                  ++pcScene->mNumMaterials;
  1205              }
  1206          }
  1207      }
  1208
  1209      // allocate the output material array
  1210      pcScene->mMaterials = new aiMaterial *[pcScene->mNumMaterials];
  1211      D3DS::Material **pcIntMaterials = new D3DS::Material *[pcScene->mNumMaterials];
  1212
  1213      unsigned int iNum = 0;
  1214      for (unsigned int iMat = 0; iMat < mParser->m_vMaterials.size(); ++iMat) {
  1215          ASE::Material &mat = mParser->m_vMaterials[iMat];
  1216          if (mat.bNeed) {
  1217              ai_assert(nullptr != mat.pcInstance);
  1218              pcScene->mMaterials[iNum] = mat.pcInstance;
  1219
  1220              // Store the internal material, too
  1221              pcIntMaterials[iNum] = &mat;
  1222
  1223              // Iterate through all meshes and search for one which is using
  1224              // this top-level material index
  1225              for (unsigned int iMesh = 0; iMesh < pcScene->mNumMeshes; ++iMesh) {
  1226                  aiMesh *mesh = pcScene->mMeshes[iMesh];
  1227                  if (ASE::Face::DEFAULT_MATINDEX == mesh->mMaterialIndex &&
  1228                          iMat == (uintptr_t)mesh->mColors[3]) {
  1229                      mesh->mMaterialIndex = iNum;
  1230                      mesh->mColors[3] = nullptr;
  1231                  }
  1232              }
  1233              iNum++;
  1234          }
  1235          for (unsigned int iSubMat = 0; iSubMat < mat.avSubMaterials.size(); ++iSubMat) {
  1236              ASE::Material &submat = mat.avSubMaterials[iSubMat];
  1237              if (submat.bNeed) {
  1238                  ai_assert(nullptr != submat.pcInstance);
  1239                  pcScene->mMaterials[iNum] = submat.pcInstance;
  1240
  1241                  // Store the internal material, too
  1242                  pcIntMaterials[iNum] = &submat;
  1243
  1244                  // Iterate through all meshes and search for one which is using
  1245                  // this sub-level material index
  1246                  for (unsigned int iMesh = 0; iMesh < pcScene->mNumMeshes; ++iMesh) {
  1247                      aiMesh *mesh = pcScene->mMeshes[iMesh];
  1248
  1249                      if (iSubMat == mesh->mMaterialIndex && iMat == (uintptr_t)mesh->mColors[3]) {
  1250                          mesh->mMaterialIndex = iNum;
  1251                          mesh->mColors[3] = nullptr;
  1252                      }
  1253                  }
  1254                  iNum++;
  1255              }

930          for (unsigned int i = 0; i < mesh.mFaces.size(); ++i) {
   931              // check range
   932              if (mesh.mFaces[i].iMaterial >= vSubMaterials.size()) {
   933                  ASSIMP_LOG_WARN("Submaterial index is out of range");
   934
   935                  // use the last material instead
   936                  aiSplit[vSubMaterials.size() - 1].push_back(i);
   937              } else
   938                  aiSplit[mesh.mFaces[i].iMaterial].push_back(i);
   939          }
   940
   941          // now generate submeshes
   942          for (unsigned int p = 0; p < vSubMaterials.size(); ++p) {
   943              if (!aiSplit[p].empty()) {
   944
   945                  aiMesh *p_pcOut = new aiMesh();
   946                  p_pcOut->mPrimitiveTypes = aiPrimitiveType_TRIANGLE;
   947
   948                  // let the sub material index
   949                  p_pcOut->mMaterialIndex = p;
   950
   951                  // we will need this material
   952                  mParser->m_vMaterials[mesh.iMaterialIndex].avSubMaterials[p].bNeed = true;
   953
   954                  // store the real index here ... color channel 3
   955                  p_pcOut->mColors[3] = (aiColor4D *)(uintptr_t)mesh.iMaterialIndex;
   956
   957                  // store a pointer to the mesh in color channel 2
   958                  p_pcOut->mColors[2] = (aiColor4D *)&mesh;
   959                  avOutMeshes.push_back(p_pcOut);
   960
   961                  // convert vertices
   962                  p_pcOut->mNumVertices = (unsigned int)aiSplit[p].size() * 3;
   963                  p_pcOut->mNumFaces = (unsigned int)aiSplit[p].size();
   964
   965                  // receive output vertex weights
   966                  std::vector<std::pair<unsigned int, float>> *avOutputBones = nullptr;
   967                  if (!mesh.mBones.empty()) {
   968                      avOutputBones = new std::vector<std::pair<unsigned int, float>>[mesh.mBones.size()];
   969                  }
   970
   971                  // allocate enough storage for faces
   972                  p_pcOut->mFaces = new aiFace[p_pcOut->mNumFaces];
   973
   974                  unsigned int iBase = 0, iIndex;
   975                  if (p_pcOut->mNumVertices) {
   976                      p_pcOut->mVertices = new aiVector3D[p_pcOut->mNumVertices];
   977                      p_pcOut->mNormals = new aiVector3D[p_pcOut->mNumVertices];
   978                      for (unsigned int q = 0; q < aiSplit[p].size(); ++q) {
   979
   980                          iIndex = aiSplit[p][q];
   981
   982                          p_pcOut->mFaces[q].mIndices = new unsigned int[3];
   983                          p_pcOut->mFaces[q].mNumIndices = 3;
   984
   985                          for (unsigned int t = 0; t < 3; ++t, ++iBase) {
   986                              const uint32_t iIndex2 = mesh.mFaces[iIndex].mIndices[t];
   987
   988                              p_pcOut->mVertices[iBase] = mesh.mPositions[iIndex2];
   989                              p_pcOut->mNormals[iBase] = mesh.mNormals[iIndex2];
   990
   991                              // convert bones, if existing
   992                              if (!mesh.mBones.empty()) {
   993                                  ai_assert(avOutputBones);
   994                                  // check whether there is a vertex weight for this vertex index
   995                                  if (iIndex2 < mesh.mBoneVertices.size()) {
   996
   997                                      for (std::vector<std::pair<int, float>>::const_iterator
   998                                                      blubb = mesh.mBoneVertices[iIndex2].mBoneWeights.begin();
   999                                              blubb != mesh.mBoneVertices[iIndex2].mBoneWeights.end(); ++blubb) {
  1000
  1001                                          // NOTE: illegal cases have already been filtered out
  1002                                          avOutputBones[(*blubb).first].emplace_back(
  1003                                                  iBase, (*blubb).second);
  1004                                      }
  1005                                  }
  1006                              }
  1007                              p_pcOut->mFaces[q].mIndices[t] = iBase;
  1008                          }
  1009                      }
  1010                  }
  1011                  // convert texture coordinates (up to AI_MAX_NUMBER_OF_TEXTURECOORDS sets supported)
  1012                  for (unsigned int c = 0; c < AI_MAX_NUMBER_OF_TEXTURECOORDS; ++c) {
  1013                      if (!mesh.amTexCoords[c].empty()) {
  1014                          p_pcOut->mTextureCoords[c] = new aiVector3D[p_pcOut->mNumVertices];
  1015                          iBase = 0;
  1016                          for (unsigned int q = 0; q < aiSplit[p].size(); ++q) {
  1017                              iIndex = aiSplit[p][q];
  1018                              for (unsigned int t = 0; t < 3; ++t) {
  1019                                  p_pcOut->mTextureCoords[c][iBase++] = mesh.amTexCoords[c][mesh.mFaces[iIndex].mIndices[t]];
  1020                              }
  1021                          }
  1022                          // Setup the number of valid vertex components
  1023                          p_pcOut->mNumUVComponents[c] = mesh.mNumUVComponents[c];
  1024                      }
  1025                  }
  1026
  1027                  // Convert vertex colors (only one set supported)
  1028                  if (!mesh.mVertexColors.empty()) {
  1029                      p_pcOut->mColors[0] = new aiColor4D[p_pcOut->mNumVertices];
  1030                      iBase = 0;
  1031                      for (unsigned int q = 0; q < aiSplit[p].size(); ++q) {
  1032                          iIndex = aiSplit[p][q];
  1033                          for (unsigned int t = 0; t < 3; ++t) {
